file.content:
            if (
                not isinstance(items, list)
                or not items
                or len(items) > 100
            ):
                _request_invalid()
                return

            # 先判定每项外层结构并收集结构合法项的锚点查询，批初原子
            # 读取一次本租户锚点快照（required_use 恒为 status）。
            well_formed: List[bool] = []
            queries: List[Tuple[str, int, str]] = []
            for item in items:
                if (
                    isinstance(item, dict)
                    and set(item) == {"manifest", "ndjson"}
                    and isinstance(item["manifest"], dict)
                    and isinstance(item["ndjson"], str)
                    and self._receipt_consumption_manifest_is_well_formed(
                        item["manifest"]
                    )
                ):
                    well_formed.append(True)
                    queries.append(
                        (
                            item["manifest"]["signer_did"],
                            item["manifest"]["key_version"],
                            "status",
                        )
                    )
                else:
                    well_formed.append(False)

            snapshot_pems = (
                store.get_active_trust_anchor_public_key_snapshot(
                    tenant, queries
                )
                if queries
                else []
            )
            anchor_snapshot: Dict[Tuple[str, int], Optional[str]] = {}
            for (did, key_version, _use), public_pem in zip(
                queries, snapshot_pems
            ):
                anchor_snapshot[(did, key_version)] = public_pem

            results: List[Dict[str, Any]] = []
            for index, item in enumerate(items):  # 顺序校验，失败不短路
                if not well_formed[index]:
                    results.append({"valid": False, "reason": "清单非法"})
                    continue
                reason = self._verify_credential_status_receipt_consumption_manifest_item(
                    tenant,
                    item["manifest"],
                    item["ndjson"],
                    anchor_snapshot=anchor_snapshot,
                )
                if reason is None:
                    results.append({"valid": True})
                else:
                    results.append({"valid": False, "reason": reason})
            self._send_json(200, {"results": results})

        def _post_trust_credential_status_receipt_sync(
            self, tenant: str
        ) -> None:
            # POST /v1/trust/credential-status/receipt-sync：同步外系统
            # 凭证状态回执消费历史并防重放。除下列差异外，请求结构、
            # 400 外层错误、清单验真五阶段及固定 reason、游标窗口、检查点
            # 续页与重放/409 冲突、201/200 成功响应、500 回滚、并发、
            # 重启与不审计语义完整复用 POST /v1/trust/receipt-sync：
            # 1) 清单验真锚点用途改为 status（复用凭证状态回执消费历史
            #    清单验真）；
            # 2) NDJSON 逐字复用同目录凭证状态回执消费历史 export；
            # 3) 检查点与同步索引独立于普通验真回执同步，仍按租户、
            #    signer_did 隔离；
            # 4) 成功响应键序恰为 valid、signer_did、snapshot、
            #    next_after、count。
            data = self._read_json()
            if set(data) != {"manifest", "ndjson"}:
                missing = [f for f in ("manifest", "ndjson") if f not in data]
                if missing:
                    raise ValidationError(
                        f"请求缺少字段: {', '.join(missing)}"
                    )
                extra = sorted(set(data) - {"manifest", "ndjson"})
                raise ValidationError(f"请求含多余字段: {', '.join(extra)}")
            manifest = data["manifest"]
            ndjson = data["ndjson"]
            if not isinstance(manifest, dict):
                raise ValidationError(
                    "请求不合法: 字段 manifest 必须为 JSON 对象"
                )
            if not isinstance(ndjson, str):
                raise ValidationError(
                    "请求不合法: 字段 ndjson 必须为字符串"
                )

            # 阶段一：清单验真（锚点用途为 status，五段固定 reason）。
            reason = (
                self._verify_credential_status_receipt_consumption_manifest_item(
                    tenant, manifest, ndjson
                )
            )
            if reason is not None:
                self._send_json(200, {"valid": False, "reason": reason})
                return

            signer_did = manifest["signer_did"]
            snapshot = manifest["snapshot"]
            after = manifest["filters"]["after"]

            # 阶段二：NDJSON 结构、游标窗口与页内重复键（与普通回执
            # 同步同一解析协议，行形状逐字复用状态回执消费历史 export）。
            events = self._parse_receipt_sync_ndjson(
                ndjson, after, snapshot
            )
            if events is None:
                self._send_json(
                    200, {"valid": False, "reason": "导出内容非法"}
                )
                return

            # 阶段三：独立检查点推进、历史重复键与原子落盘。
            try:
                created, effective_snapshot, next_after, count = (
                    store.sync_credential_status_receipt_consumptions(
                        tenant, signer_did, snapshot, after, events
                    )
                )
            except ConflictError:
                self._send_error(409, "同步游标冲突")
                return
            except ValidationError:
                self._send_json(
                    200, {"valid": False, "reason": "导出内容非法"}
                )
                return
            except StorageError:
                self._send_error(500, "存储失败")
                return
            self._send_json(
                201 if created else 200,
                {
                    "valid": True,
                    "signer_did": signer_did,
                    "snapshot": effective_snapshot,
                    "next_after": next_after,
                    "count": count,
                },
            )

        def _get_trust_credential_status(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
            # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
            # 探测。已同步仅返回 status、reason、updated_at。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_synced_credential_status(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                },
            )

        def _get_trust_imported_credential(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET /v1/trust/credentials/imported/{credential_id}
            # ?issuer_did=...：issuer_did 须唯一且非空，缺失/重复/空值
            # 一律 400；未导入、跨租户或 issuer_did 不匹配（含他租户
            # 双键）404，存在性不可探测。成功 200 返回键序
            # issuer_did,credential_id,body,signature。纯只读，不写状态、
            # 不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_imported_credential(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
